        'quiet=${(now - busyLastEventMs) ~/ 1000}s',
      );
      return (
        copyWith(
          busy: false,
          busyStartedAtMs: -1,
          busyPhase: '',
          busySource: '',
          busyLastEventMs: -1,
          stickyLines: const [],
          stickyIndex: -1,
        ),
        null,
      );
