+        .split('[[rules]]')
+        .firstWhere((b) => b.contains('id = "busy_row"'));
+    final facePattern = RegExp(
+      r"line_regex = \['(.+?)', ",
+    ).firstMatch(busyRule)!.group(1)!;
+    final faceRe = RegExp(facePattern);
+
+    const faces = [
+      '>_o', '-_-', 'o_o', '>_<', 'o_<', '◕‿◕', '¬_¬', 'o_o?',
