  // stay visible while idle — a pending reminder is exactly what the user
  // needs to see when nothing else is happening.
  if (plan.scheduled > 0) {
    b.writeln(_scheduledRowLine());
    row++;
  }
  row = _writeJobBoard(b, row, plan);
  row = _writeWaitingRows(b, row, plan);

