+    }
+    // Widest face needs no zone pad; 3-cell faces pad with one space.
+    expect(busyRowOf(faceModel(7)), startsWith('o_o? W'));
+    expect(busyRowOf(faceModel(2)), startsWith('o_o  W'));
+  });
