      final (exe, exeArgs) = CliVisualHarness.resolveFaCommand(
        args: ['--model', 'm'],
        executableArgs: ['/repo/bin/fah.dart', '--theme', 'dark'],
        ambientFaBin: '/ambient/fa',
      );
      expect(exe, 'dart');
      expect(exeArgs, ['/repo/bin/fah.dart', '--theme', 'dark']);
