/// The live busy-row line from the real frame painter (`FaTuiModel.view()`,
/// the same seam `fa_tui_busy_row_test.dart` pins), ANSI-stripped and
/// trimmed — the bytes herdr's engine reads off the emulated screen.
/// `source: 'run'` because every interactive run brackets with
/// `sendBusy(true, source: 'run')` (agent_cli.dart).
String _liveBusyLine({String phase = '', required int elapsed, int frame = 1}) {
  final ansi = RegExp(r'\x1b\[[0-9;?]*[A-Za-z]');
  var model = FaTuiModel(
    callbacks: FaTuiCallbacks(
      onSubmit: (_, {images = const []}) async {},
      onModelSelected: (_) async {},
      buildSlashMenu: (_) => const [],
      buildModelMenu: (_, _) => const [],
      statusLine: () => '',
      prompt: '',
    ),
    isExited: () => false,
    termWidth: 80,
    kaomojiPick: (_) => 0, // fixtures pin the face — no randomness
  );
  model = model.update(const BusyMsg(true, source: 'run')).$1 as FaTuiModel;
  final now = DateTime.now().millisecondsSinceEpoch;
  model = model.copyWith(
    busyStartedAtMs: now - elapsed * 1000,
    busyLastEventMs: now,
    busyPhase: phase,
    kaomojiFace: frame,
  );
  return model
      .view()
      .content
      .split('\n')
      .map((l) => l.replaceAll(ansi, ''))
      .firstWhere((l) => l.contains('· run'))
      .trimRight();
}

/// The busy row opens with one of the eight kaomoji faces (issue #1374),
/// padded into a fixed 4-cell zone — one or two spaces before the label
/// (`  ?` in the manifest: the not-gate's inline extractor forbids brace
/// quantifiers). The two ASCII fallback faces (`^.^`, `-_/-narrow`) are
/// matched too.
final _busyLineRe = RegExp(
  r'^(>_o|-_-|o_o|>_<|o_<|◕‿◕|¬_¬|o_o\?|\^\.\^|-_/)  ?',
);

String _fixtureBusyLine(String name) => File(
  '$_fixturesDir/$name',
).readAsStringSync().split('\n').firstWhere(_busyLineRe.hasMatch);

void main() {
  final manifest = _parseFaManifest(File(_manifestPath).readAsStringSync());

  test('manifest shape matches what herdr bundles', () {
    expect(manifest.id, 'fa');
    expect(manifest.aliases, contains('herdr:fa'));
    // Engine 2 (any/not gates); never above what current herdr bundles.
    expect(manifest.minEngineVersion, lessThanOrEqualTo(2));
    expect(
      manifest.rules.map((r) => r.id),
      containsAll(<String>[
        'approval_sheet',
        'secret_sheet',
        'busy_row',
        'composer_gutter',
      ]),
    );
    for (final rule in manifest.rules) {
      expect(rule.state, isIn(['working', 'blocked', 'idle', 'unknown']));
      expect(rule.gate.hasPositiveMatcher, isTrue, reason: rule.id);
    }
  });

  test('every committed fixture classifies to its state', () {
    final expected = {
      'working.txt': 'working',
      'working-classic.txt': 'working',
      // A mid-run phase label (tool execution) must classify busy — the
      // busy_row rule keys on the spinner + elapsed cells, not the label.
      'working-phase.txt': 'working',
      'idle.txt': 'idle',
